  "source": "pragma cashscript ^0.14.0;\n\n// LaunchDesk escrow v2 (behind ESCROW_V2=1): v1 (LaunchDeskEscrow.cash) plus an on-chain receipt for the customer.\n//\n// Same two ways out as v1:\n//   release(): LaunchDesk release key AND a report signature over orderId ++ reportHash. Output 0 pays the merchant\n//              (no tokens), output 1 is OP_RETURN \"LD1\" <reportHash>, and when the escrowed coin sits at outpoint\n//              index 0 of its funding tx (the LaunchDesk wallet flow always builds it that way) output 2 MUST be the\n//              customer's receipt: exactly `receiptSats` to the customer's own address (refundPkh) carrying a new\n//              immutable NFT whose category is the funding txid (a CashTokens genesis from this very input) and whose\n//              commitment is reportHash. So the customer's wallet holds proof of which report they paid for.\n//              A token genesis is only possible from an input spending outpoint index 0; a coin at any other index\n//              (someone paid with a hand-built tx) is released exactly like v1, without the receipt.\n//   refund():  unchanged from v1: after `timeout` blocks, no signature, everything (minus a capped fee) back to the\n//              customer.\ncontract LaunchDeskEscrowV2(\n    bytes20 merchantPkh,   // where a release pays out (the LaunchDesk merchant wallet, P2PKH)\n    pubkey releasePk,      // server hot key that signs the release transaction\n    pubkey oraclePk,       // key that signs \"this report was delivered for this order\" (may equal releasePk)\n    bytes20 refundPkh,     // the customer's own address (P2PKH): refund AND receipt NFT go here\n    int timeout,           // refund unlocks after this many blocks since funding (6 = about 1 hour)\n    bytes32 orderId        // sha256 of the order reference; also makes every order address unique\n) {\n    function release(sig releaseSig, datasig reportSig, bytes32 reportHash) {\n        require(checkSig(releaseSig, releasePk));\n        require(checkDataSig(reportSig, orderId + reportHash, oraclePk));\n\n        require(tx.inputs.length == 1);\n\n        int amount = tx.inputs[this.activeInputIndex].value;\n        require(tx.outputs[0].lockingBytecode == new LockingBytecodeP2PKH(merchantPkh));\n        require(tx.outputs[0].tokenCategory == 0x);\n\n        require(tx.outputs[1].value == 0);\n        require(tx.outputs[1].lockingBytecode == new LockingBytecodeNullData([0x4c4431, reportHash]));\n        require(tx.outputs[1].tokenCategory == 0x);\n\n        if (tx.inputs[this.activeInputIndex].outpointIndex == 0) {\n            require(tx.outputs.length == 3);\n            require(tx.outputs[0].value >= amount - 3000);\n            require(tx.outputs[2].lockingBytecode == new LockingBytecodeP2PKH(refundPkh));\n            require(tx.outputs[2].value == 1000);\n            require(tx.outputs[2].tokenCategory == tx.inputs[this.activeInputIndex].outpointTransactionHash);\n            require(tx.outputs[2].nftCommitment == reportHash);\n            require(tx.outputs[2].tokenAmount == 0);\n        } else {\n            require(tx.outputs.length == 2);\n            require(tx.outputs[0].value >= amount - 2000);\n        }\n    }\n\n    function refund() {\n        require(this.age >= timeout);\n\n        require(tx.inputs.length == 1);\n        require(tx.outputs.length == 1);\n\n        int amount = tx.inputs[this.activeInputIndex].value;\n        require(tx.outputs[0].lockingBytecode == new LockingBytecodeP2PKH(refundPkh));\n        require(tx.outputs[0].value >= amount - 2000);\n        require(tx.outputs[0].tokenCategory == 0x);\n    }\n}\n",
